# Generators of Groups

p = 28151
## For the finite field with p=28151 find the smallest element g which is a primitive element of F_p​.

p = 28151
def prime_factors(n):
    i = 2
    factors = set()
    while i * i <= n:
        if n % i == 0:
            factors.add(i)
            while n % i == 0:
                n //= i
        i += 1
    if n > 1:
        factors.add(n)
    return factors

factors = prime_factors(p - 1)
g = 2
while True:
    if all(pow(g, (p - 1) // q, p) != 1 for q in factors):
        break
    g += 1
print(g) # 7

